763	 *
764	 * Rendered and parsed back rather than trusted, because escaping and parsing have to
765	 * agree: a character `escapeLabel` does not neutralise is an upload that cannot be undone
766	 * and a picture that links elsewhere. The URL is a stand-in — the real one does not exist
767	 * until the asset has uploaded, and only the alt text varies.
768	 */
769	export function isSingleImage(markdown: string, url: string): boolean {
770	  if (!markdown.startsWith("![")) return false;
771	  let index = 2;
772	  while (index < markdown.length) {
773	    const character = markdown[index]!;
774	    if (character === "\\") {
775	      index += 2;
776	      continue;
777	    }
778	    if (character === "]") break;
779	    index += 1;
780	  }
781	  if (markdown[index] !== "]") return false;
782	  return markdown.slice(index + 1) === `(${url})`;
