845	export function resolveAttachFiles(files: { path: string; name?: string; alt?: string }[]): AttachFile[] {
846	  const out: AttachFile[] = [];
847	
848	  for (const file of files) {
849	    const source = sourceWithinRun(file.path);
850	    let size: number;
851	    try {
852	      const stats = statSync(source);
853	      if (stats.isDirectory()) {
854	        throw new Error(`'${file.path}' is a directory (${source}); an attachment is one regular file.`);
855	      }
856	      if (!stats.isFile()) {
857	        throw new Error(
858	          `'${file.path}' is not a regular file (${source}); a pipe or a device is read forever rather than uploaded.`,
859	        );
860	      }
861	      size = stats.size;
862	    } catch (error) {
863	      const message = error instanceof Error ? error.message : "";
864	      if (message.includes("is a directory") || message.includes("is not a regular file")) throw error;
865	      throw new Error(`could not read '${file.path}': no such file at ${source}`);
866	    }
867	    if (size === 0) {
868	      throw new Error(`'${file.path}' is empty (${source}); an empty file uploads and renders as a broken attachment.`);
869	    }
870	
871	    const name = file.name ?? basename(source);
872	    assertFileName(name, file.path);
873	    const type = attachTypeFor(name);
874	    const ceiling = ceilingFor(type.rendering);
875	    if (size > ceiling) {
876	      throw new Error(
877	        `${source} is ${size} bytes, and ${ceilingReason(type.rendering, ceiling)}. ` +
878	          `'.${type.extension}' is a ${type.rendering}, so nothing was uploaded.`,
879	      );
880	    }
881	
882	    out.push({
883	      path: file.path,
884	      source,
885	      name,
886	      alt: altFor(file, name, type),
887	      size,
888	      rendering: type.rendering,
889	      contentType: type.contentType,
890	    });
891	  }
892	
893	  return out;
894	}
