1	/**
2	 * hardened-servers.test.ts — the list in `docs/tools/boundaries.md` of the servers
3	 * that harden themselves, held to the servers that actually do.
4	 *
5	 * ## Why this exists
6	 *
7	 * The page is prose and the call is code, and nothing connected the two. At the
8	 * commit this was written on the list named five servers, `atoma` among them — a
9	 * name no entry in `defaults.yaml` has ever had — while seven of the shipped
10	 * programs call `hardenCredentialHolder` at startup. `files` has called it since the
11	 * initial commit and was named by no version of that list; `attachments` was added
12	 * and never added to it. A reader has no reason to run the grep that would notice,
13	 * so a drift here ships.
14	 *
15	 * ## What is read
16	 *
17	 * `defaults.yaml` says which servers ship and which program each starts; `src/` says
18	 * which programs harden. Both directions are then required of the page: every program
19	 * that hardens is named, and nothing is named whose program does not.
20	 *
21	 * The comparison is over **programs, not names**, because three pairs of entries are
22	 * one program started twice — `files`/`files_readonly`, `atomaton`/`atomaton_env`,
23	 * `delegate`/`delegate_readonly`. A name is accepted if the program it starts hardens,
24	 * so either entry of a pair is a true statement about what the run does, and what is
25	 * refused is a name that hardens nothing.
26	 *
27	 * `files` is also why the `env` blocks are the wrong thing to read. It declares
28	 * `env: {}` and hardens anyway: hardening does not depend on holding a credential,
29	 * because a server that ships here makes itself unreadable whether or not its own
30	 * `env` names anything — `web` is the other one. A rule written from the credentials
31	 * would be wrong in both directions.
32	 */
33	import { describe, expect, test } from "bun:test";
34	import { readFileSync } from "node:fs";
35	import { join } from "node:path";
36	import { toolDefaults } from "../../src/domain/machinery/shipped-servers.ts";
37	import { TOOLS_DIR, sourceOf } from "../../src/domain/machinery/machinery-layout.ts";
38	
39	const PAGE = "docs/tools/boundaries.md";
40	
41	/** The subject of the paragraph the list is in, on the page. */
42	const MARKER = "Credentials in the servers this project ships";
43	
44	/** How a program that hardens calls it. `tools/lib/harden.ts` owns the function. */
45	const HARDEN_CALL = /^\s*hardenCredentialHolder\(/m;
46	
47	/** What a server entry's `args` names, wherever the machinery tree is rooted. */
48	const PREFIX = "${ATOMATON_MACHINERY_ROOT:-.}/";
49	
50	/**
51	 * The source file a server entry starts, or `undefined` when the entry runs something
52	 * that is not a script of ours — which is every server a project adds.
53	 */
54	function sourceScriptOf(args: unknown): string | undefined {
55	  if (!Array.isArray(args)) return undefined;
56	  for (const arg of args.map(String)) {
57	    if (!arg.startsWith(PREFIX)) continue;
58	    const deployed = arg.slice(PREFIX.length);
59	    // Through the layout table rather than by splicing the deployed path into `src/`:
60	    // the two trees' names have nothing in common, which is what `BUILT_FROM` is for.
61	    if (!deployed.startsWith(`${TOOLS_DIR}/`)) continue;
62	    return join("src", sourceOf(TOOLS_DIR), deployed.slice(TOOLS_DIR.length + 1));
63	  }
64	  return undefined;
65	}
66	
67	/**
68	 * The shipped servers, grouped by the program each starts.
69	 *
70	 * A group is what the page has to name one of: `files` and `files_readonly` run the
71	 * same file, so a reader told `files` alone is told nothing false, while a page that
72	 * named only `files_readonly` would leave the server an agent reads files with
73	 * unmentioned.
74	 */
75	function shippedServers(): { script: string; names: string[]; hardens: boolean }[] {
76	  const groups = new Map<string, { script: string; names: string[]; hardens: boolean }>();
77	  for (const [name, server] of Object.entries(toolDefaults().servers)) {
78	    const script = sourceScriptOf(server.args);
79	    if (script === undefined) continue;
80	    let group = groups.get(script);
81	    if (group === undefined) {
82	      group = { script, names: [], hardens: HARDEN_CALL.test(readFileSync(script, "utf8")) };
83	      groups.set(script, group);
84	    }
85	    group.names.push(name);
86	  }
87	  return [...groups.values()];
88	}
89	
90	/**
91	 * The server names the page's list holds, in the order it writes them.
92	 *
93	 * The paragraph and not the page: `docs/tools/boundaries.md` backticks a dozen other
94	 * names, and reading those would make the check mean nothing.
95	 */
96	function listedServers(page: string): string[] {
97	  const start = page.indexOf(MARKER);
98	  if (start < 0) return [];
99	  // Either line ending: the pages are written by whichever checkout produced them
100	  // (git's autocrlf makes the working copy CRLF on Windows), and `\n\n` finds
101	  // nothing in a CRLF file -- the "paragraph" then ran to the end of the page and
102	  // swept in every backticked word below it.
103	  const end = page.indexOf("\n\n", start) === -1
104	    ? page.indexOf("\r\n\r\n", start)
105	    : page.indexOf("\n\n", start);
106	  const paragraph = page.slice(start, end < 0 ? undefined : end);
107	  return [...paragraph.matchAll(/`([a-z_]+)`/g)].map(([, name]) => name!);
108	}
109	
110	describe("the hardened servers the page lists", () => {
111	  const page = readFileSync(PAGE, "utf8");
112	  const programs = shippedServers();
113	  const listed = listedServers(page);
114	
115	  test("there is something on each side of the comparison", () => {
116	    // Seven of the eight programs harden, at the commit this was written on. A floor
117	    // rather than the number: an eighth is a change to `defaults.yaml` and not a defect
118	    // here, while a walk that read nothing would make the checks below pass over an
119	    // empty list.
120	    expect(programs.filter((one) => one.hardens).length).toBeGreaterThanOrEqual(4);
121	    expect(
122	      programs.some((one) => one.names.includes("shell") && !one.hardens),
123	      "the walk reaches the servers, and reaches the one that does not harden",
124	    ).toBe(true);
125	    expect(listed.length, `${PAGE} has no list under "${MARKER}"`).toBeGreaterThan(0);
126	  });
127	
128	  test("nothing is listed that does not harden", () => {
129	    const wrong = listed.filter((name) => !programs.some((one) => one.hardens && one.names.includes(name)));
130	    expect(
131	      wrong,
132	      "each of these names no shipped server whose program makes itself unreadable at startup " +
133	        "— a misspelling, a name that is not a server, or a server that does not harden",
134	    ).toEqual([]);
135	  });
136	
137	  test("every program that hardens is named", () => {
138	    const named = new Set(listed);
139	    const missing = programs
140	      .filter((one) => one.hardens && !one.names.some((name) => named.has(name)))
141	      .map((one) => one.names.join("/"));
142	    expect(
143	      missing,
144	      `a server that protects itself and is not on the list in ${PAGE}. Entries sharing a ` +
145	        "program are one line; naming any one of them is enough",
146	    ).toEqual([]);
147	  });
148	});

